<?php
namespace App\Http\Controllers;
use App\Models\{Category,Customer,Equipment,EquipmentUnit,Payment,Rental,RentalItem,Supplier,User};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Hash;
use Illuminate\Support\Str;
use Illuminate\Validation\Rule;
use Illuminate\View\View;
use Illuminate\Http\RedirectResponse;
class RentalCameraController extends Controller {
 public function loginForm():View|RedirectResponse {if(session('user_id'))return redirect('/');return view('auth.login',['setup'=>User::count()===0]);}
 public function login(Request $r):RedirectResponse {$data=$r->validate(['username'=>'required|string','password'=>'required|string']);$u=User::where('username',$data['username'])->first();if(!$u||!Hash::check($data['password'],$u->password_hash))return back()->withErrors(['username'=>'Username atau password salah.'])->onlyInput('username');$r->session()->regenerate();$r->session()->put('user_id',$u->id);return redirect('/');}
 public function setupForm():View {abort_if(User::count()>0,403,'Akun admin sudah dibuat.');return view('auth.setup');}
 public function setup(Request $r):RedirectResponse {abort_if(User::count()>0,403,'Akun admin sudah dibuat.');$d=$r->validate(['name'=>'required|string|max:120','username'=>'required|alpha_dash|min:3|max:60|unique:users,username','password'=>'required|string|min:8']);User::create(['name'=>$d['name'],'username'=>$d['username'],'password_hash'=>Hash::make($d['password']),'role'=>'admin']);return redirect('/login')->with('success','Admin berhasil dibuat. Silakan masuk.');}
 public function logout(Request $r):RedirectResponse {$r->session()->invalidate();$r->session()->regenerateToken();return redirect('/login');}
 public function editForm(Request $r,string $type,int $id):View|RedirectResponse {if(!session('user_id'))return redirect('/login');$user=User::findOrFail(session('user_id'));abort_unless(in_array($type,['categories','customers','equipment'],true),404);if($type!=='customers')abort_if($user->role!=='admin',403,'Fitur ini khusus admin.');$record=match($type){'categories'=>Category::findOrFail($id),'customers'=>Customer::findOrFail($id),'equipment'=>Equipment::with('units')->findOrFail($id)};return view('edit-resource',['type'=>$type,'record'=>$record,'user'=>$user,'page'=>$type,'categories'=>Category::orderBy('name')->get()]);}
 public function index(Request $r):View|RedirectResponse {if(!session('user_id'))return redirect('/login');$u=User::find(session('user_id'));if(!$u){session()->invalidate();return redirect('/login');}$page=$r->query('page','dashboard');$allowed=['dashboard','rentals','equipment','customers','categories','suppliers','users','payments','reports','more'];if(!in_array($page,$allowed,true))$page='dashboard';$data=['page'=>$page,'user'=>$u,'isAdmin'=>$u->role==='admin','categories'=>Category::orderBy('name')->get(),'customers'=>Customer::orderBy('name')->get(),'units'=>EquipmentUnit::with('equipment')->orderBy('id')->get(),'equipment'=>Equipment::with('category','units')->orderBy('brand')->orderBy('model')->get(),'suppliers'=>Supplier::orderBy('name')->get(),'rentals'=>Rental::with('customer','items')->latest()->limit(100)->get(),'payments'=>Payment::with('rental')->latest('paid_at')->limit(100)->get(),'stats'=>['unit'=>EquipmentUnit::count(),'available'=>EquipmentUnit::where('status','available')->count(),'active'=>Rental::whereIn('status',['active','late'])->count(),'customers'=>Customer::count(),'low'=>Equipment::whereHas('units',fn($q)=>$q->where('status','available'),'<=' ,1)->count(),'revenue'=>Payment::whereIn('payment_type',['rental_fee','late_fee'])->sum('amount')]];
  if(in_array($page,['categories','customers','equipment'],true)&&$r->filled('edit'))$data['editItem']=match($page){'categories'=>Category::findOrFail($r->integer('edit')),'customers'=>Customer::findOrFail($r->integer('edit')),'equipment'=>Equipment::with('units')->findOrFail($r->integer('edit'))};
  if($page==='equipment'){$q=trim($r->query('q',''));$cat=$r->integer('cat');$status=$r->query('status');$sort=$r->query('sort','brand');$dir=strtoupper($r->query('dir','ASC'));$columns=['brand'=>'equipment.brand','model'=>'equipment.model','sku'=>'equipment.sku','rate'=>'equipment.daily_rate','category'=>'categories.name'];if(!isset($columns[$sort]))$sort='brand';if(!in_array($dir,['ASC','DESC'],true))$dir='ASC';$data['items']=EquipmentUnit::query()->with(['equipment.category'])->join('equipment','equipment.id','=','equipment_units.equipment_id')->join('categories','categories.id','=','equipment.category_id')->select('equipment_units.*')->when($q!=='',fn($x)=>$x->where(fn($w)=>$w->where('equipment.brand','like',"%$q%") ->orWhere('equipment.model','like',"%$q%") ->orWhere('equipment.sku','like',"%$q%") ->orWhere('equipment_units.serial_number','like',"%$q%")))->when($cat,fn($x)=>$x->where('equipment.category_id',$cat))->when(in_array($status,['available','rented','maintenance','retired'],true),fn($x)=>$x->where('equipment_units.status',$status))->orderBy($columns[$sort],$dir)->paginate(10)->withQueryString();$data+=compact('q','cat','status','sort','dir');}
  if($page==='reports')$data['report']=Category::withCount('equipment')->with(['equipment.units'])->get();
  if($page==='rentals')$data['available']=EquipmentUnit::with('equipment')->where('status','available')->get();
  if($page==='suppliers'&&$u->role!=='admin')abort(403,'Fitur khusus admin.');if($page==='users'&&$u->role!=='admin')abort(403,'Staff tidak dapat mengelola akun.');if($page==='payments'&&$u->role!=='admin')abort(403,'Fitur pembayaran khusus admin.');
  return view('app',$data);
 }
 public function action(Request $r,string $action):RedirectResponse {if(!session('user_id'))return redirect('/login');$u=User::findOrFail(session('user_id'));$admin=fn()=>abort_if($u->role!=='admin',403,'Akses ditolak: hanya admin.');$page='dashboard';
  switch($action){
   case 'customer':$id=$r->integer('id');$d=$r->validate(['name'=>'required|string|max:120','phone'=>'required|string|max:30','email'=>'nullable|email|max:150','identity_number'=>'nullable|string|max:60','address'=>'nullable|string']);if($id)Customer::findOrFail($id)->update($d);else Customer::create($d);$page='customers';break;
   case 'category':$admin();$id=$r->integer('id');$d=$r->validate(['name'=>['required','string','max:100',Rule::unique('categories','name')->ignore($id?:null)],'description'=>'nullable|string|max:255']);if($id)Category::findOrFail($id)->update($d);else Category::create($d);$page='categories';break;
   case 'delete_category':$admin();$category=Category::findOrFail($r->integer('id'));if($category->equipment()->exists())throw \Illuminate\Validation\ValidationException::withMessages(['delete'=>'Kategori masih dipakai peralatan dan tidak dapat dihapus.']);$category->delete();$page='categories';break;
   case 'equipment':$admin();$id=$r->integer('id');$rules=['category_id'=>'required|exists:categories,id','sku'=>['required','string','max:50',Rule::unique('equipment','sku')->ignore($id?:null)],'brand'=>'required|string|max:80','model'=>'required|string|max:120','daily_rate'=>'required|numeric|min:0','deposit_amount'=>'required|numeric|min:0','description'=>'nullable|string'];if(!$id)$rules['serial_number']='required|string|max:100|unique:equipment_units,serial_number';$d=$r->validate($rules);if($id)Equipment::findOrFail($id)->update(collect($d)->except('serial_number')->all());else DB::transaction(function()use($d){$e=Equipment::create(collect($d)->except('serial_number')->all());$e->units()->create(['serial_number'=>$d['serial_number'],'status'=>'available']);});$page='equipment';break;
   case 'delete_equipment':$admin();$equipment=Equipment::with('units')->findOrFail($r->integer('id'));if(RentalItem::whereIn('equipment_unit_id',$equipment->units->pluck('id'))->exists())throw \Illuminate\Validation\ValidationException::withMessages(['delete'=>'Peralatan punya riwayat sewa dan tidak dapat dihapus.']);DB::transaction(function()use($equipment){$equipment->suppliers()->detach();$equipment->units()->delete();$equipment->delete();});$page='equipment';break;
   case 'delete_customer':$customer=Customer::findOrFail($r->integer('id'));if($customer->rentals()->exists())throw \Illuminate\Validation\ValidationException::withMessages(['delete'=>'Pelanggan punya riwayat sewa dan tidak dapat dihapus.']);$customer->delete();$page='customers';break;
   case 'create_rental':$d=$r->validate(['customer_id'=>'required|exists:customers,id','unit_id'=>'required|exists:equipment_units,id','start_at'=>'required|date','due_at'=>'required|date|after:start_at']);$start=\Carbon\Carbon::parse($d['start_at']);$due=\Carbon\Carbon::parse($d['due_at']);$days=max(1,(int)ceil($start->diffInSeconds($due)/86400));DB::transaction(function()use($d,$u,$start,$due,$days){$unit=EquipmentUnit::with('equipment')->lockForUpdate()->findOrFail($d['unit_id']);if($unit->status!=='available')throw \Illuminate\Validation\ValidationException::withMessages(['unit_id'=>'Unit tidak tersedia untuk disewa.']);$overlap=RentalItem::where('equipment_unit_id',$unit->id)->whereHas('rental',fn($q)=>$q->whereIn('status',['booked','active','late'])->where('start_at','<',$due)->where('due_at','>',$start))->exists();if($overlap)throw \Illuminate\Validation\ValidationException::withMessages(['unit_id'=>'Jadwal unit bertabrakan dengan transaksi lain.']);$total=(float)$unit->equipment->daily_rate*$days;$r=Rental::create(['rental_code'=>'RC-'.now()->format('ymd').'-'.Str::upper(Str::random(6)),'customer_id'=>$d['customer_id'],'created_by'=>$u->id,'start_at'=>$start,'due_at'=>$due,'status'=>'active','subtotal'=>$total,'deposit_total'=>$unit->equipment->deposit_amount]);RentalItem::create(['rental_id'=>$r->id,'equipment_unit_id'=>$unit->id,'daily_rate'=>$unit->equipment->daily_rate,'rental_days'=>$days,'line_total'=>$total]);$unit->update(['status'=>'rented']);});$page='rentals';break;
   case 'return_rental':$d=$r->validate(['rental_id'=>'required|exists:rentals,id']);DB::transaction(function()use($d){$rental=Rental::with('items')->lockForUpdate()->findOrFail($d['rental_id']);if(!in_array($rental->status,['active','late'],true))throw \Illuminate\Validation\ValidationException::withMessages(['rental_id'=>'Transaksi tidak aktif atau sudah dikembalikan.']);foreach($rental->items as $item)EquipmentUnit::whereKey($item->equipment_unit_id)->where('status','rented')->update(['status'=>'available']);$rental->update(['status'=>'completed','returned_at'=>now()]);});$page='rentals';break;
   case 'supplier':$admin();$d=$r->validate(['name'=>'required|string|max:140','contact_name'=>'nullable|string|max:120','phone'=>'required|string|max:30','email'=>'nullable|email|max:150']);Supplier::create($d);$page='suppliers';break;
   case 'link_supplier':$admin();$d=$r->validate(['equipment_id'=>'required|exists:equipment,id','supplier_id'=>'required|exists:suppliers,id','price'=>'required|numeric|min:0']);Equipment::findOrFail($d['equipment_id'])->suppliers()->syncWithoutDetaching([$d['supplier_id']=>['supplier_price'=>$d['price']]]);$page='suppliers';break;
   case 'user':$admin();$d=$r->validate(['name'=>'required|string|max:120','username'=>'required|alpha_dash|min:3|max:60|unique:users,username','password'=>'required|string|min:8','role'=>['required',Rule::in(['admin','staff'])]]);User::create(['name'=>$d['name'],'username'=>$d['username'],'password_hash'=>Hash::make($d['password']),'role'=>$d['role']]);$page='users';break;
   case 'payment':$admin();$d=$r->validate(['rental_id'=>'required|exists:rentals,id','type'=>['required',Rule::in(['rental_fee','late_fee','refund'])],'amount'=>'required|numeric|gt:0','method'=>['required',Rule::in(['cash','transfer','card','other'])],'note'=>'nullable|string|max:255']);Payment::create(['rental_id'=>$d['rental_id'],'received_by'=>$u->id,'payment_type'=>$d['type'],'amount'=>$d['amount'],'method'=>$d['method'],'note'=>$d['note']??null]);$page='payments';break;
   default:abort(404);
  }
  return redirect('/?page='.$page)->with('success','Data berhasil disimpan.');
 }
}

